/**
 * Paula DMA Audio Streamer for Web Audio API.
 *
 * Bridges 16-bit interleaved PCM samples generated by the WASM Amiga Core
 * into the browser's Web Audio graph with smooth playback, anti-click ramping,
 * and automatic silence when stopped or reset.
 */

export interface WasmAudioCoreLike {
  memory: WebAssembly.Memory;
  rgme_audio_ptr?(): number;
  rgme_audio_samples?(): number;
}

export class WasmAudioStreamer {
  private ctx: AudioContext | null = null;
  private gainNode: GainNode | null = null;
  private scriptNode: ScriptProcessorNode | null = null;
  private queue: Float32Array[] = [];
  private volume = 0.8;
  private isMuted = false;
  private isRunning = false;

  constructor(private readonly getContext: () => AudioContext | null) {}

  start(core: WasmAudioCoreLike): void {
    if (this.isRunning) return;
    this.ctx = this.getContext();
    if (!this.ctx) return;

    if (this.ctx.state === "suspended") {
      void this.ctx.resume();
    }

    this.gainNode = this.ctx.createGain();
    this.gainNode.gain.setValueAtTime(this.isMuted ? 0 : this.volume, this.ctx.currentTime);
    this.gainNode.connect(this.ctx.destination);

    // Buffer size: 2048 samples (~46ms at 44.1kHz)
    this.scriptNode = this.ctx.createScriptProcessor(2048, 0, 2);
    this.scriptNode.onaudioprocess = (e) => {
      const outL = e.outputBuffer.getChannelData(0);
      const outR = e.outputBuffer.getChannelData(1);

      if (this.queue.length === 0 || !this.isRunning) {
        outL.fill(0);
        outR.fill(0);
        return;
      }

      let offset = 0;
      while (offset < outL.length && this.queue.length > 0) {
        const chunk = this.queue[0]!;
        const needed = outL.length - offset;
        const available = chunk.length / 2;

        if (available <= needed) {
          for (let i = 0; i < available; i++) {
            outL[offset + i] = chunk[i * 2]!;
            outR[offset + i] = chunk[i * 2 + 1]!;
          }
          offset += available;
          this.queue.shift();
        } else {
          for (let i = 0; i < needed; i++) {
            outL[offset + i] = chunk[i * 2]!;
            outR[offset + i] = chunk[i * 2 + 1]!;
          }
          this.queue[0] = chunk.subarray(needed * 2);
          offset += needed;
        }
      }

      if (offset < outL.length) {
        outL.fill(0, offset);
        outR.fill(0, offset);
      }
    };

    this.scriptNode.connect(this.gainNode);
    this.isRunning = true;
  }

  pumpFrame(core: WasmAudioCoreLike): void {
    if (!this.isRunning || !core.rgme_audio_ptr || !core.rgme_audio_samples) return;

    const count = core.rgme_audio_samples();
    if (count <= 0) return;

    const ptr = core.rgme_audio_ptr();
    const pcm = new Int16Array(core.memory.buffer, ptr, count * 2);

    const f32 = new Float32Array(count * 2);
    for (let i = 0; i < count * 2; i++) {
      f32[i] = pcm[i]! / 32768;
    }

    // Limit queue size to avoid latency accumulation (max ~200ms)
    if (this.queue.length > 10) {
      this.queue.shift();
    }
    this.queue.push(f32);
  }

  setVolume(vol: number): void {
    this.volume = Math.max(0, Math.min(1, vol));
    if (this.gainNode && this.ctx && !this.isMuted) {
      this.gainNode.gain.setValueAtTime(this.volume, this.ctx.currentTime);
    }
  }

  setMute(mute: boolean): void {
    this.isMuted = mute;
    if (this.gainNode && this.ctx) {
      this.gainNode.gain.setValueAtTime(mute ? 0 : this.volume, this.ctx.currentTime);
    }
  }

  stop(): void {
    this.isRunning = false;
    this.queue = [];
    if (this.scriptNode) {
      try {
        this.scriptNode.disconnect();
      } catch {
        /* ignore */
      }
      this.scriptNode = null;
    }
    if (this.gainNode) {
      try {
        this.gainNode.disconnect();
      } catch {
        /* ignore */
      }
      this.gainNode = null;
    }
  }
}
